mapping = compound_head(page)->mapping;
if (!mapping) {
	int shmem_swizzled = PageSwapCache(page);
	key->shared.inode = mapping->host;
get_futex_key_refs(key); /* implies smp_mb(); (B) */

unlock_page(page);

